CREATE TRIGGER IF NOT EXISTS security_cap_parse_jobs BEFORE INSERT ON parse_jobs WHEN NOT EXISTS(SELECT 1 FROM parse_jobs WHERE id=NEW.id) AND (SELECT COUNT(*) FROM parse_jobs)>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;
CREATE TRIGGER IF NOT EXISTS security_cap_telegram_updates BEFORE INSERT ON telegram_updates WHEN NOT EXISTS(SELECT 1 FROM telegram_updates WHERE update_id=NEW.update_id) AND (SELECT COUNT(*) FROM telegram_updates)>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;
CREATE TRIGGER IF NOT EXISTS security_cap_telegram_inbox BEFORE INSERT ON telegram_inbox WHEN NOT EXISTS(SELECT 1 FROM telegram_inbox WHERE update_id=NEW.update_id) AND (SELECT COUNT(*) FROM telegram_inbox)>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;
