CREATE TRIGGER IF NOT EXISTS security_cap_teacher_settings BEFORE INSERT ON teacher_settings WHEN NOT EXISTS(SELECT 1 FROM teacher_settings WHERE key=NEW.key) AND (SELECT COUNT(*) FROM teacher_settings)>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;